import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';

// 90mm M3-inspired gun — ORIGINAL mesh, generated by scripts/modelgen/player_gun_90mm.py.
// Long tube + recoil sleeve + double-baffle muzzle brake. Breech at origin,
// tip at +Z ≈ 3.47 after the runtime rotation.

export default {
  id: 'player-gun-90mm',
  name: '90mm M3',
  category: 'cannon',
  stats: {
    caliber: 90,
    barrelLength: 2.90,
    elevation: 20,
    depression: 10,
  },

  async build(scene, material) {
    const result = await SceneLoader.ImportMeshAsync(
      '', '/assets/models/tanks/parts/', 'player_gun_90mm.glb', scene
    );

    const root = new TransformNode('gunPlayer90_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) {
      m.setParent(root);
      m.material = material;
    }

    // Set rotation AFTER parenting — same reason as the other cannon modules.
    root.rotation.x = Math.PI / 2;

    return { root, meshes, breech: new Vector3(0, 0, 0) };
  },
};
